role_settings_sql.value:
-- §5d — bounds a noisy neighbour on the shared instance. Idempotent.
ALTER ROLE rova SET statement_timeout = '30s';
ALTER ROLE rova SET idle_in_transaction_session_timeout = '60s';
ALTER ROLE rova CONNECTION LIMIT 40;

-- The migrator needs the long fuse §4 sets deliberately: the default kills a
-- slow migration part-way, which is the worst possible moment.
ALTER ROLE rova_migrator SET statement_timeout = '600s';
ALTER ROLE rova_migrator SET idle_in_transaction_session_timeout = '0';

